import pennywise, datetime, decimal
from decimal import Decimal
txt = "# household, March\n2024-03-01 salary 2500.00 March pay\n2024-03-02 groceries -42.50 weekly shop\n\n2024-03-05 Rent -900\n"
es = pennywise.parse(txt)
print(es)
e=es[0]; print(type(e.date), type(e.category), type(e.amount), repr(es[2].note))
print(repr(pennywise.balance(es)), repr(pennywise.balance([])), repr(pennywise.balance(iter(es))))
print(pennywise.by_category(es), pennywise.by_month(es), type(pennywise.by_month(es)))
print(pennywise.by_category([]), pennywise.by_month(iter(es)))
print(pennywise.filter_entries(es, category="RENT"))
print(len(pennywise.filter_entries(es, since=datetime.date(2024,3,2), until=datetime.date(2024,3,5))))
print(len(pennywise.filter_entries(es, since=datetime.date(2024,3,2), until=datetime.date(2024,3,2))))
print(pennywise.filter_entries(es) == es, pennywise.filter_entries(es) is es)
for bad in ["2024-02-30 a 1", "x\n\n# c\n2024-01-01 a 12.505", "2024-01-01 a 1,000.00", "2024-01-01 a abc", "2024-01-01"]:
    try: pennywise.parse(bad)
    except pennywise.ParseError as ex: print(isinstance(ex, ValueError), ex.line, str(ex))
for ok in ["2024-01-01 a 2500","2024-01-01 a +2500","2024-01-01 a 2500.00","2024-01-01 a 12.5","2024-01-01 a -0.99", "2024-01-01\ta\t\t5\t  note  with   spaces \t "]:
    print(repr(pennywise.parse(ok)[0]))
print(pennywise.parse(""), pennywise.parse("\n\n# x\n"))
# precision
big = [pennywise.Entry(datetime.date(2024,1,1),"a",Decimal("1"+"0"*40)), pennywise.Entry(datetime.date(2024,1,1),"a",Decimal("0.01"))]
print(pennywise.balance(big), pennywise.by_category(big))
print(decimal.getcontext().prec)
print(pennywise.parse("2024-01-01 a 1\x0c\n2024-01-02 b 2 x\n"))
print(pennywise.parse("2024-01-01 a 1\r\n2024-01-02 b 2\rbad")[0] if False else "")
try: pennywise.parse("2024-01-01 a 1\r\n2024-01-02 b 2\rbad")
except pennywise.ParseError as ex: print(ex.line, ex)
print(pennywise.Entry(datetime.date(2024,1,1),"a",Decimal(1)).note == "")
try: es[0].amount = 1
except Exception as ex: print(type(ex).__name__)
# float amount / non-finite in library input
try: print(pennywise.balance([pennywise.Entry(datetime.date(2024,1,1),"a",Decimal("NaN"))]))
except Exception as ex: print("nan:", type(ex).__name__, ex)
try: print(pennywise.balance([pennywise.Entry(datetime.date(2024,1,1),"a",Decimal("1E+5"))]))
except Exception as ex: print("exp:", type(ex).__name__, ex)
try: print(pennywise.balance([pennywise.Entry(datetime.date(2024,1,1),"a",1)]))
except Exception as ex: print("int:", type(ex).__name__, ex)
EOF

